-- 1. Ensure any extended columns exist before data insert
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS banner_url TEXT;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS has_custom_avatar BOOLEAN DEFAULT FALSE;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS has_custom_banner BOOLEAN DEFAULT FALSE;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS department TEXT;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS lab_group TEXT;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS primary_field TEXT;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS secondary_fields TEXT[] DEFAULT '{}';
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS degree_program TEXT;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS graduation_year INTEGER;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS google_scholar_url TEXT;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS researchgate_url TEXT;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS linkedin_url TEXT;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS scopus_id TEXT;
ALTER TABLE public.paper_authors ADD COLUMN IF NOT EXISTS created_at TIMESTAMPTZ DEFAULT NOW();
ALTER TABLE public.post_topics ADD COLUMN IF NOT EXISTS created_at TIMESTAMPTZ DEFAULT NOW();
ALTER TABLE public.comments ADD COLUMN IF NOT EXISTS path LTREE;

-- 2. Temporarily drop foreign key constraint on profiles.id referencing auth.users
-- (Allows existing profiles to exist seamlessly even before users re-authenticate)
ALTER TABLE public.profiles DROP CONSTRAINT IF EXISTS profiles_id_fkey;

