  ('e2e6bf3b-5c24-4c7f-b04d-b64cf365e730', 'revered_sage', 'S S Mishra', 'https://lvstuqhrmagzqkgwlisl.supabase.co/storage/v1/object/public/profile-media/e2e6bf3b-5c24-4c7f-b04d-b64cf365e730/avatar_1791263628437.jpg?t=1791263630204', 'In Training Student Researcher', 'AINN', 'Student researcher and Co-Founder of BooffIn. Exploring neuroscience and complex biological systems through research, computation, and interdisciplinary thinking. Building systems that connect evidence rather than simplify it. Learning continuously, questioning assumptions, and letting the data decide.', '', NULL, NULL, FALSE, NULL, '{"Neuroscience","AI in Science","Genetics & Genomics","Cancer Biology","Quantum Physics","Biophysics","Bioinformatics","Data Science","Artificial Intelligence","Molecular & Cell Biology"}', 7, 4, 0, 0, '2026-09-25T17:58:14.840713+00:00', 'https://lvstuqhrmagzqkgwlisl.supabase.co/storage/v1/object/public/profile-media/e2e6bf3b-5c24-4c7f-b04d-b64cf365e730/banner_1791267810481.jpg?t=1791267827692', TRUE, TRUE, '2026-10-14T06:04:59.018673+00:00', NULL, NULL, NULL, '{}', NULL, NULL, NULL, NULL, NULL, NULL),
