INSERT INTO public.papers (id, doi, canonical_url, title, abstract, journal, publisher, publication_date, publication_year, open_access_status, open_access_pdf_url, citation_count, discussion_count, likes_count, saves_count, created_at, updated_at)
VALUES
  ('5793f915-d714-48a1-a819-3a60c7a02734', '10.1038/s41586-024-0001-x', 'https://doi.org/10.1038/s41586-024-0001-x', 'Deep learning architectures reveal structural dynamics of synaptic plasticity', 'We introduce an automated machine learning approach to reconstruct 3D dendritic spine reorganization from high-resolution in vivo optical microscopy.', 'Nature Neuroscience', NULL, NULL, 2026, 'gold', NULL, 0, 1, 0, 0, '2026-09-26T11:58:04.025053+00:00', '2026-09-26T11:58:04.025053+00:00'),
  ('4c8b02be-2b63-4cde-ac2c-c758aad767ea', '10.3389/fcimb.2020.00121', 'https://doi.org/10.3389/fcimb.2020.00121', 'Plasmodium Perforin-Like Protein Pores on the Host Cell Membrane Contribute in Its Multistage Growth and Erythrocyte Senescence', 'The pore forming Plasmodium Perforin Like Proteins (PPLP), expressed in all stages of the parasite life cycle are critical for completion of the parasite life cycle. The high sequence similarity in the central Membrane Attack Complex/ Perforin (MACPF) domain among PLPs and their distinct functional overlaps define them as lucrative target for developing multi-stage antimalarial therapeutics. Herein, we evaluated the mechanism of Pan-active MACPF Domain (PMD), a centrally located and highly conserved region of PPLPs, and deciphered the inhibitory potential of specifically designed PMD inhibitors. The E. coli expressed rPMD interacts with erythrocyte membrane and form pores of ~10.5 nm height and ~24.3 nm diameter leading to hemoglobin release and dextran uptake. The treatment with PMD induced erythrocytes senescence which can be hypothesised to account for the physiological effect of disseminated PLPs in loss of circulating erythrocytes inducing malaria anemia. The anti-PMD inhibitors effectively blocked intraerythrocytic growth by suppressing invasion and egress processes and protected erythrocytes against rPMD induced senescence. Moreover, these inhibitors also blocked the hepatic stage and transmission stage parasite development suggesting multi-stage, transmission-blocking potential of these inhibitors. Concievably, our study has introduced a novel set of anti-PMD inhibitors with pan-inhibitory activity against all the PPLPs members which can be developed into potent cross-stage antimalarial therapeutics along with erythrocyte senescence protective potential to occlude PPLPs mediated anemia in severe malaria.', 'Frontiers in Cellular and Infection Microbiology', 'Frontiers Media', '2020-03-24', 2020, 'gold', 'https://www.frontiersin.org/articles/10.3389/fcimb.2020.00121/pdf', 0, 0, 0, 0, '2026-09-26T17:47:55.943659+00:00', '2026-09-26T17:47:55.943659+00:00'),
  ('f61b60b7-7edd-4885-8029-3e4822be3db5', '10.1007/s12035-026-06117-y', 'https://doi.org/10.1007/s12035-026-06117-y', 'Integrated Identification of NAD⁺ Metabolism-Associated Candidate Genes', 'Migraine is one of the most disabling neurological diseases globally; however, a significant proportion of patients do not respond to current treatments, or treatment efficacy diminishes over time, highlighting the need to identify additional molecular candidates for further investigation. Recent studies have increasingly focused on the role of neuro-immune interactions in migraine. This study aimed to identify peripheral immune-related candidate genes associated with NAD + metabolism-related transcriptional features in migraine through integrated bulk and single-cell transcriptomic analyses. Using the PRJEB40032 dataset, samples were stratified according to ssGSEA-derived NAD + metabolism scores, followed by differential expression analysis, weighted gene co-expression network analysis and protein-protein interaction network construction. LASSO regression, SVM-RFE, and XGBoost were subsequently applied to prioritize candidate genes. CXCL8, CXCR4, CXCL1, and TNFAIP3 showed cross-algorithm consistency and were subsequently incorporated into an exploratory nomogram, which exhibited apparent discriminatory performance within the PRJEB40032 discovery cohort. Functional enrichment analysis revealed that these genes were associated with immune and inflammatory pathways, including IL-17, NF-κB, TNF, and Toll-like receptor signaling. Immune cell-composition analysis indicated significantly increased estimated abundances or activity scores for NK cells, mast cells, eosinophils, and neutrophils in migraine samples, with positive associations between the prioritized candidate genes and pro-inflammatory immune features. Single-cell RNA sequencing further showed that CXCL1 and CXCL8 were predominantly expressed in monocytes, while TNFAIP3 and CXCR4 were widely expressed across various immune cell types. qPCR assessment in a migraine mouse model showed group-dependent expression alterations in the functionally related murine CXCL1/CXCR2 axis. Overall, this study prioritized peripheral immune-related candidate genes associated with migraine and NAD⁺ metabolism-related transcriptional features, providing exploratory evidence for a potential link among systemic immune alterations, NAD⁺ metabolism-related processes, and migraine.', 'Molecular Neurobiology', 'Springer Science+Business Media', '2026-01-01', 2026, 'gold', 'https://link.springer.com/content/pdf/10.1007/s12035-026-06117-y.pdf', 0, 0, 0, 1, '2026-09-29T04:21:15.58519+00:00', '2026-09-29T04:21:15.58519+00:00'),
  ('808f5d94-8476-40cd-ad72-5cad1789b727', '10.1016/j.bcp.2026.118171', 'https://doi.org/10.1016/j.bcp.2026.118171', 'Corrigendum to "''Erythritol'', a safe natural sweetener exhibits multi-stage anti-malarial activity by permeating into Plasmodium falciparum through aquaglyceroporin channel" [Biochem. Pharmacol. 205 (2022) 115287]', 'Abstract available on publisher website.', 'Biochemical pharmacology', NULL, NULL, 2026, 'gold', NULL, 0, 0, 0, 0, '2026-09-30T21:08:14.510616+00:00', '2026-09-30T21:08:14.510616+00:00'),
  ('ff65c073-cb52-4bb8-bd26-af8e029d2b61', '10.1038/s41598-023-40160-2', 'https://doi.org/10.1038/s41598-023-40160-2', 'Molecular docking as a tool for the discovery of molecular targets of nutraceuticals in diseases management', 'Molecular docking is a computational technique that predicts the binding affinity of ligands to receptor proteins. Although it has potential uses in nutraceutical research, it has developed into a formidable tool for drug development. Bioactive substances called nutraceuticals are present in food sources and can be used in the management of diseases. Finding their molecular targets can help in the creation of disease-specific new therapies. The purpose of this review was to explore molecular docking''s application to the study of dietary supplements and disease management. First, an overview of the fundamentals of molecular docking and the various software tools available for docking was presented. The limitations and difficulties of using molecular docking in nutraceutical research are also covered, including the reliability of scoring functions and the requirement for experimental validation. Additionally, there was a focus on the identification of molecular targets for nutraceuticals in numerous disease models, including those for sickle cell disease, cancer, cardiovascular, gut, reproductive, and neurodegenerative disorders. We further highlighted biochemistry pathways and models from recent studies that have revealed molecular mechanisms to pinpoint new nutraceuticals'' effects on disease pathogenesis. It is convincingly true that molecular docking is a useful tool for identifying the molecular targets of nutraceuticals in the management of diseases. It may offer information about how nutraceuticals work and support the creation of new therapeutics. Therefore, molecular docking has a bright future in nutraceutical research and has a lot of potentials to lead to the creation of brand-new medicines for the treatment of disease.', 'Scientific Reports', 'Nature Portfolio', '2023-08-17', 2023, 'gold', 'https://www.nature.com/articles/s41598-023-40160-2.pdf', 0, 4, 0, 1, '2026-09-27T11:45:12.324993+00:00', '2026-09-27T11:45:12.324993+00:00'),
  ('8a31dc6e-4217-45d0-88b5-b99c0064bedd', '10.1038/s12276-021-00571-5', 'https://doi.org/10.1038/s12276-021-00571-5', 'Zebrafish as an animal model for biomedical research', 'Zebrafish have several advantages compared to other vertebrate models used in modeling human diseases, particularly for large-scale genetic mutant and therapeutic compound screenings, and other biomedical research applications. With the impactful developments of CRISPR and next-generation sequencing technology, disease modeling in zebrafish is accelerating the understanding of the molecular mechanisms of human genetic diseases. These efforts are fundamental for the future of precision medicine because they provide new diagnostic and therapeutic solutions. This review focuses on zebrafish disease models for biomedical research, mainly in developmental disorders, mental disorders, and metabolic diseases.', 'Experimental & Molecular Medicine', 'Springer Nature', '2021-03-01', 2021, 'gold', 'https://www.nature.com/articles/s12276-021-00571-5.pdf', 0, 2, 0, 1, '2026-09-27T18:15:38.982571+00:00', '2026-09-27T18:15:38.982571+00:00'),
  ('c4f397a9-a80c-4ba3-b8dc-cbd06db5fa17', '10.1162/jocn.a.2688', 'https://doi.org/10.1162/jocn.a.2688', 'Neural Organization of Episodic Memory and Navigation in Children and Adults', 'Episodic memory and spatial navigation are often viewed as interlinked, in part due to their shared reliance on medial-temporal lobe (MTL) structures. At the same time, there are important differences, for example, natural spatial navigation requires moving one''s body through space while episodic memory does not. We investigated whether naturalistically encoded memories that were either episodic or additionally embedded in a navigational experience relied on overlapping or distinct neural networks. Children ages 8-13 years old and young adults viewed pictures of objects that they had previously encountered in real-world experiences, either on a tour of a new environment or seated in a room, along with novel objects. Univariate fMRI analyses revealed tour-related activity in entorhinal (ERC) and perirhinal (PRC) cortices that differed between early adolescents and adults. Functional connectivity between ERC and PRC for episodic memory decreased with age. Exploratory findings suggested behavior-driven connectivity among the hippocampus, ERC, and lateral occipital cortex to support reconstruction of the spatial context. Naturalistic episodic and spatial contexts are processed in the MTL, but these regions may interact somewhat differently in episodic and navigational contexts, and in late childhood and early adolescence versus early adulthood.', 'Journal of cognitive neuroscience', NULL, NULL, 2028, 'gold', NULL, 0, 0, 0, 0, '2026-09-30T21:39:09.858847+00:00', '2026-09-30T21:39:09.858847+00:00'),
  ('4ab83ea6-45de-44fa-b827-75804d1cd41d', '10.1242/dmm.052921', 'https://doi.org/10.1242/dmm.052921', 'Cardiac magnetic resonance imaging reveals myocardial fibrosis and systolic dysfunction in mitochondrial trifunctional protein-deficient mice', 'Cardiomyopathy is an important manifestation in patients with fatty acid oxidation disorders and represents a major cause of morbidity and early mortality in mitochondrial trifunctional protein (TFP) deficiency. Although a mouse model carrying the TFP β-subunit p.Met404Lys mutation (βTFP-deficient mice) has been described, cardiac involvement in this model has not been systematically characterized. Here, we combined cardiac histology and multiparametric cardiac magnetic resonance imaging (CMR) to define myocardial structure, function and tissue characteristics in this mouse model. Histological analysis with automated whole-slide collagen quantification revealed myocardial fibrosis with collagen deposition in mutant hearts, and CMR demonstrated increased myocardial extracellular volume in both male and female homozygous mutants. Homozygous males showed reduced ejection fraction, impaired systolic strain and increased left ventricular end-systolic volume, indicating systolic dysfunction. Male mice were more severely affected than females and exhibited reduced survival. Together, these findings demonstrate that βTFP-deficient mice develop fibrotic cardiomyopathy with systolic dysfunction, reproducing important cardiac features observed in human TFP deficiency. This work establishes the model as a relevant platform for investigating disease mechanisms and therapeutic strategies for cardiomyopathy in TFP deficiency.', 'Disease models & mechanisms', NULL, NULL, 2026, 'gold', NULL, 0, 0, 0, 0, '2026-10-01T03:03:17.735605+00:00', '2026-10-01T03:03:17.735605+00:00'),
  ('919e1118-35a3-492e-9c1a-705918898640', NULL, 'https://arxiv.org/abs/2208.02561', 'Cosmic Acceleration and the notion of Alternative Vacuum in Nash Theory', 'We argue that Nash theory, a quadratic theory of Gravity, can describe a late-time cosmic acceleration without any exotic matter or cosmological constant. The observational viability of an exact cosmological solution of Nash theory is adjudged using a Markov chain Monte Carlo simulation and JLA+OHD+BAO data sets. Departures from standard ΛCDM cosmology are noted and analyzed. We prove that the Nash vacuum dynamics is equivalent to the dynamics of an Einstein vacuum plus a self-interacting Higgs scalar field, only if a mild evolution of the Higgs Vacuum Expectation Value is allowed. This leads to variations in the mass scales of fundamental particles and the fine structure constant. The variations are found to fit nicely with the analysis of molecular absorption spectra from a series of Quasars.', 'arXiv Preprint', NULL, NULL, 2022, 'gold', 'https://arxiv.org/pdf/2208.02561.pdf', 0, 0, 0, 0, '2026-10-01T06:51:53.130403+00:00', '2026-10-01T06:51:53.130403+00:00'),
  ('d848d06d-1fcb-4c18-8cd6-4bd20b0e636a', NULL, 'https://arxiv.org/abs/1706.03762', 'Attention Is All You Need', 'The dominant sequence transduction models are based on complex recurrent or convolutional neural networks in an encoder-decoder configuration. The best performing models also connect the encoder and decoder through an attention mechanism. We propose a new simple network architecture, the Transformer, based solely on attention mechanisms, dispensing with recurrence and convolutions entirely. Experiments on two machine translation tasks show these models to be superior in quality while being more parallelizable and requiring significantly less time to train. Our model achieves 28.4 BLEU on the WMT 2014 English-to-German translation task, improving over the existing best results, including ensembles by over 2 BLEU. On the WMT 2014 English-to-French translation task, our model establishes a new single-model state-of-the-art BLEU score of 41.8 after training for 3.5 days on eight GPUs, a small fraction of the training costs of the best models from the literature. We show that the Transformer generalizes well to other tasks by applying it successfully to English constituency parsing both with large and limited training data.', 'arXiv Preprint', 'Cornell University', '2017-06-12T17:57:34Z', 2017, 'gold', 'https://arxiv.org/pdf/1706.03762.pdf', 0, 0, 0, 0, '2026-10-01T07:17:22.564939+00:00', '2026-10-01T07:17:22.564939+00:00'),
  ('ca44ea3a-e877-438c-9ccb-3124ce9a6d2f', '10.1371/journal.pntd.0013726', 'https://doi.org/10.1371/journal.pntd.0013726', 'Reversal of filarial serpin Wb123-urokinase plasminogen activator receptor mediated alternative macrophage activation by monoclonal antibody', 'Potent inflammatory responses from host-parasite interactions in lymphatic filariasis are driven by macrophage polarization, which critically determines parasite survival or clearance. Evidence suggests that filarial parasite promote alternative macrophage polarization, facilitating immune evasion and persistent infection. However, the precise molecular mechanisms underlying filaria-induced alternative macrophage activation remain to be fully elucidated. Recently, serine protease inhibitors (serpins) have been implicated in alternative immune activation. Building on this insight, we explored and identified putative filarial serpins to be highly expressed in the infective L3 larval stage using in-silico analysis approach. Among all, Wb123, a serpin of Wuchereria bancrofti, the most predominantly found filarial worm, was cloned and purified to establish its role in alternative activation. We observed elevated markers of alternative activation; namely CD163, arginase-1, IL-6 and pSTAT3 expression, following rWb123 treatment. Furthermore, our results also indicated that rWb123 interacts with urokinase plasminogen activator receptor (uPAR) to activate the alternative activation pathway. Interestingly, rWb123 treatment attenuated the classical macrophage activation induced by lipopolysaccharide (LPS) and interferon-gamma (IFN-γ) as evident from muted CD86, nitric oxide (NO) and reactive oxygen species (ROS) expression. Notably, use of monoclonal antibody (MAbG8) to rWb123 or blocking uPAR impedes the rWb123-induced alternative activation and rescues the proinflammatory response to LPS-IFN-γ. These data confirmed that, uPAR dependent alternative activation by Wb123 enables filarial parasites to evade a strong pro-inflammatory immune response. Thus, targeting filarial serpins or uPAR could be potential therapeutics to re-establish immune response and eliminate filarial parasite from host.', 'PLoS neglected tropical diseases', NULL, NULL, 2025, 'gold', 'https://europepmc.org/articles/PMC12768378?pdf=render', 0, 0, 0, 0, '2026-10-02T16:15:13.132038+00:00', '2026-10-02T16:15:13.132038+00:00'),
  ('557efdb8-38dc-4b80-b492-46dfb5efc24d', '10.1038/s41586-021-03819-2', 'https://doi.org/10.1038/s41586-021-03819-2', 'Highly accurate protein structure prediction with AlphaFold', 'Abstract Proteins are essential to life, and understanding their structure can facilitate a mechanistic understanding of their function. Through an enormous experimental effort 1–4 , the structures of around 100,000 unique proteins have been determined 5 , but this represents a small fraction of the billions of known protein sequences 6,7 . Structural coverage is bottlenecked by the months to years of painstaking effort required to determine a single protein structure. Accurate computational approaches are needed to address this gap and to enable large-scale structural bioinformatics. Predicting the three-dimensional structure that a protein will adopt based solely on its amino acid sequence—the structure prediction component of the ‘protein folding problem’ 8 —has been an important open research problem for more than 50 years 9 . Despite recent progress 10–14 , existing methods fall far short of atomic accuracy, especially when no homologous structure is available. Here we provide the first computational method that can regularly predict protein structures with atomic accuracy even in cases in which no similar structure is known. We validated an entirely redesigned version of our neural network-based model, AlphaFold, in the challenging 14th Critical Assessment of protein Structure Prediction (CASP14) 15 , demonstrating accuracy competitive with experimental structures in a majority of cases and greatly outperforming other methods. Underpinning the latest version of AlphaFold is a novel machine learning approach that incorporates physical and biological knowledge about protein structure, leveraging multi-sequence alignments, into the design of the deep learning algorithm.', 'Nature', 'Nature Portfolio', '2021-07-15', 2021, 'gold', 'https://www.nature.com/articles/s41586-021-03819-2.pdf', 0, 6, 0, 3, '2026-10-01T07:26:27.60534+00:00', '2026-10-01T07:26:27.60534+00:00'),
  ('82288911-6964-4847-b726-1be21cb00afb', NULL, 'https://arxiv.org/abs/1706.03762', 'Attention Is All You Need', 'The dominant sequence transduction models are based on complex recurrent or convolutional neural networks in an encoder-decoder configuration. The best performing models also connect the encoder and decoder through an attention mechanism. We propose a new simple network architecture, the Transformer, based solely on attention mechanisms, dispensing with recurrence and convolutions entirely. Experiments on two machine translation tasks show these models to be superior in quality while being more parallelizable and requiring significantly less time to train. Our model achieves 28.4 BLEU on the WMT 2014 English-to-German translation task, improving over the existing best results, including ensembles by over 2 BLEU. On the WMT 2014 English-to-French translation task, our model establishes a new single-model state-of-the-art BLEU score of 41.8 after training for 3.5 days on eight GPUs, a small fraction of the training costs of the best models from the literature. We show that the Transformer generalizes well to other tasks by applying it successfully to English constituency parsing both with large and limited training data.', 'arXiv Preprint', 'Cornell University', '2017-06-12T17:57:34Z', 2017, 'gold', 'https://arxiv.org/pdf/1706.03762.pdf', 0, 1, 0, 1, '2026-10-01T07:22:37.182472+00:00', '2026-10-01T07:22:37.182472+00:00'),
  ('1fff43d1-4c79-41cd-81fb-7bdb84455f8d', '10.4103/indianjpsychiatry.indianjpsychiatry_120_24', 'https://doi.org/10.4103/indianjpsychiatry.indianjpsychiatry_120_24', 'Quantitative EEG correlates of ''Kriya yoga'' benefits for mental health among health care providers', 'BackgroundHealth care workers (HCWs) experience abounding physical and mental exhaustion mandating a deliverable solution for their mental health care. Kriya yoga (KY) includes several relaxation techniques and offers a stress-alleviating experience. The objective signature of KY benefits needs to be investigated.AimTo study the effects of KY practice on brain oscillations and perceived stress in health care providers.MethodsThis prospective interventional study was conducted during coronavirus disease 2019 pandemic. HCWs were enrolled to the intervention group (IG) and control group (CG) after obtaining an informed consent. IG visited the yoga center for learning the KY technique. Electroencephalogram (EEG) was recorded in both the groups, at baseline, and at the end of 6 weeks in the EEG Laboratory. Perceived stress scale (PSS) scores and participants'' subjective response to KY practice were also collected. Paired t-test and independent t-test were used for statistical comparison wherever applicable.ResultsAge and baseline EEG powers among the IG and CG (N = 25) were statistically comparable. Absolute power analysis revealed a statistically significant increase in alpha and delta powers after 6 weeks of KY practice. The PSS scores revealed a statistically significant decrease in perceived stress after KY practice. Furthermore, 83% of the participants reported the subjective calming effects of KY practice.ConclusionKY practice ensues relaxing effects on the brain, as evident from the EEG absolute power analysis, PSS scores, and participants'' subjective response. As KY is a brief technique, it may be encouraged during short break session among the HCWs for promotive health.', 'Indian journal of psychiatry', NULL, NULL, 2024, 'gold', 'https://europepmc.org/backend/ptpmcrender.fcgi?accid=PMC11382751&blobtype=pdf', 0, 0, 0, 0, '2026-10-04T18:03:29.728722+00:00', '2026-10-04T18:03:29.728722+00:00'),
  ('f2515efc-533c-49ea-b8e9-ffd1f97b9ee5', '10.1093/bioinformatics/btag724', 'https://doi.org/10.1093/bioinformatics/btag724', 'COCOA.jl – A Julia package for high-performance anal y sis of concordance and kinetic modules in biochemical networks', 'MOTIVATION: Recent advances in analysis of biochemical networks have contributed the identification of their modular structure based on the concept of multi reaction dependencies and kinetic coupling of reaction rates (Küken et al., 2022; Langary et al., 2025). Existing implementations of the algorithms to study modular structure do not scale well with the size of the networks, prohibiting their application with genome-scale networks. RESULTS: Here, we introduce COCOA.jl, a multithreaded Julia package for identification of concordant and kinetic modules, with applications in the study of concentration robustness. AVAILABILITY: COCOA.jl is implemented in Julia 1.12.6 and is freely available under the MIT license at GitHub (https://github.com/antoniofranky/COCOA.jl) and Zenodo (https://doi.org/10.5281/zenodo.22094185). It runs on Linux, macOS, and Windows; installation is supported via the Julia package manager. COCOA.jl can be called from Python via JuliaCall. SUPPLEMENTARY INFORMATION: Supplementary data are available at Bioinformatics online.', 'Bioinformatics', NULL, NULL, 2026, 'gold', 'https://academic.oup.com/bioinformatics/advance-article-pdf/doi/10.1093/bioinformatics/btag724/71448651/btag724.pdf', 0, 0, 0, 0, '2026-10-03T14:12:33.588184+00:00', '2026-10-03T14:12:33.588184+00:00'),
  ('e8d1da2f-5d20-4695-8912-898f77d05c37', '10.1038/srep05510', 'https://doi.org/10.1038/srep05510', 'Natural small-molecule enhancers of autophagy induce autophagic cell death in apoptosis-defective cells', 'Resistance of cancer cells to chemotherapy is a significant problem in oncology and the development of sensitising agents or small-molecules with new mechanisms of action to kill these cells is needed. Autophagy is a cellular process responsible for the turnover of misfolded proteins or damaged organelles and it also recycles nutrients to maintain energy levels for cell survival. In some apoptosis-resistant cancer cells, autophagy can also enhance the efficacy of anti-cancer drugs through autophagy-mediated mechanisms of cell death. Because the modulation of autophagic processes can be therapeutically useful to circumvent chemoresistance and enhance the effects of cancer treatment, the identification of novel autophagic enhancers for use in oncology is highly desirable. Many novel anti-cancer compounds have been isolated from natural products; therefore, we worked to discover natural, anti-cancer small-molecule enhancers of autophagy. Here, we have identified a group of natural alkaloid small-molecules that function as novel autophagic enhancers. These alkaloids, including liensinine, isoliensinine, dauricine and cepharanthine, stimulated AMPK-mTOR dependent induction of autophagy and autophagic cell death in a panel of apoptosis-resistant cells. Taken together, our work provides novel insights into the biological functions, mechanisms and potential therapeutic values of alkaloids for the induction of autophagy.', 'Scientific Reports', NULL, NULL, 2014, 'gold', 'https://www.nature.com/articles/srep05510.pdf', 0, 0, 0, 0, '2026-10-05T17:30:51.622365+00:00', '2026-10-05T17:30:51.622365+00:00'),
  ('2e77261b-6493-457d-8306-587cf1edb53b', '10.1021/acs.jmedchem.4c00811', 'https://doi.org/10.1021/acs.jmedchem.4c00811', 'Occurrence of “Natural Selection” in Successful Small Molecule Drug Discovery', 'Published compounds from ChEMBL version 32 are used to seek evidence for the occurrence of “natural selection” in drug discovery. Three measures of natural product (NP) character were applied, to compare time- and target-matched compounds reaching the clinic (clinical compounds in phase 1–3 development and approved drugs) with background compounds (reference compounds). Pseudo-NPs (PNPs), containing NP fragments combined in ways inaccessible by nature, are increasing over time, reaching 67% of clinical compounds first disclosed since 2010. PNPs are 54% more likely to be found in post-2008 clinical versus reference compounds. The majority of target classes show increased clinical compound NP character versus their reference compounds. Only 176 NP fragments appear in >1000 clinical compounds published since 2008, yet these make up on average 63% of the clinical compound’s core scaffolds. There is untapped potential awaiting exploitation, by applying nature’s building blocks—“natural intelligence”—to drug design.', 'Journal of Medicinal Chemistry', NULL, NULL, 2024, 'gold', 'https://europepmc.org/articles/PMC11247505?pdf=render', 0, 0, 0, 0, '2026-10-05T17:31:38.173251+00:00', '2026-10-05T17:31:38.173251+00:00'),
  ('fb9b410f-0a5f-4cb0-a788-04ab35899035', '10.1523/jneurosci.4632-15.2016', 'https://doi.org/10.1523/jneurosci.4632-15.2016', 'Behavioral, Neurophysiological, and Synaptic Impairment in a Transgenic Neuregulin1 (NRG1-IV) Murine Schizophrenia Model', 'UnlabelledSchizophrenia is a chronic, disabling neuropsychiatric disorder with complex genetic origins. The development of strategies for genome manipulation in rodents provides a platform for understanding the pathogenic role of genes and for testing novel therapeutic agents. Neuregulin 1 (NRG1), a critical developmental neurotrophin, is associated with schizophrenia. The NRG1 gene undergoes extensive alternative splicing and, to date, little is known about the neurobiology of a novel NRG1 isoform, NRG1-IV, which is increased in the brains of individuals with schizophrenia and associated with genetic risk variation. Here, we developed a transgenic mouse model (NRG1-IV/NSE-tTA) in which human NRG1-IV is selectively overexpressed in a neuronal specific manner. Using a combination of molecular, biochemical, electrophysiological, and behavioral analyses, we demonstrate that NRG1-IV/NSE-tTA mice exhibit abnormal behaviors relevant to schizophrenia, including impaired sensorimotor gating, discrimination memory, and social behaviors. These neurobehavioral phenotypes are accompanied by increases in cortical expression of the NRG1 receptor, ErbB4 and the downstream signaling target, PIK3-p110δ, along with disrupted dendritic development, synaptic pathology, and altered prefrontal cortical excitatory-inhibitory balance. Pharmacological inhibition of p110δ reversed sensorimotor gating and cognitive deficits. These data demonstrate a novel role for NRG1-IV in learning, memory, and neural circuit formation and a potential neurobiological mechanism for schizophrenia risk; show that deficits are pharmacologically reversible in adulthood; and further highlight p110δ as a target for antipsychotic drug development.Significance statementSchizophrenia is a disabling psychiatric disorder with neurodevelopmental origins. Genes that increase risk for schizophrenia have been identified. Understanding how these genes affect brain development and function is necessary. This work is the first report of a newly generated humanized transgenic mouse model engineered to express human NRG1-IV, an isoform of the NRG1 (Neuregulin 1) gene that is increased in the brains of patients with schizophrenia in association with genetic risk. Using behavioral neuroscience, molecular biology, electrophysiology, and pharmacology, we identify a role for NRG1-IV in learning, memory, and cognition and determine that this relates to brain excitatory-inhibitory balance and changes in ErbB4/PI3K/AKT signaling. Moreover, the study further highlights the potential of targeting the PI3K pathway for the treatment of schizophrenia.', 'The Journal of neuroscience : the official journal of the Society for Neuroscience', NULL, NULL, 2016, 'gold', 'https://europepmc.org/backend/ptpmcrender.fcgi?accid=PMC4846677&blobtype=pdf', 0, 0, 0, 0, '2026-10-07T06:40:00.300764+00:00', '2026-10-07T06:40:00.300764+00:00'),
  ('81272fba-d248-4493-aabc-decedcc8ed07', '10.26479/2018.0404.09', 'https://doi.org/10.26479/2018.0404.09', 'Determining Pluripotency of a Cell by an in Silico Method', 'While working with stem cells one of the questions that bother the researcher is about their potency to reprogram. So, if the pluripotency of cells is known beforehand, it would be an added advantage. Bioinformatics approaches have a viable solution to such concerns saving a lot on time and energy. Stem cell isolation and utilizing them for regeneration is itself a very sophisticated and dynamic concept. Thus working with such cells statistical and probabilistic aspects would be in consideration to tackle the active state. Induced pluripotent stem cells were first described by Shinya Yamanaka[1], and since then the approach towards the regenerative field of medicine has seen tremendous changes. By utilizing the bioinformatics tools and resources, few research groups have demonstrated the level of pluripotency of the cells. All available methods have different approaches and have their own set of limitations. After thorough research on such tools, we have designed a novel tool for determining the pluripotency. Unlike existing methods, our method doesn’t rely on particular cell type or specific file format to start with. It is a straightforward, quick and reliable way to check any cell’s pluripotency. The information regarding the gene expression on the pluripotent stem cells has been gathered at one place and compared with test cell, all with the help of programming languages viz. R, JAVA. Since the identification of cell is based on their genetic expression, the output is robust and reliable. It would be a key player in the field of regenerative medicine where pluripotent stem cells are being utilized for drug development and gene therapy. Further, for gene therapy and ex-vivo generation of cells determining the pluripotency of the source cells would not only increase the efficiency of the overall procedure but reduce the time and capital investment.', 'Research Journal of Life Sciences Bioinformatics Pharmaceutical and Chemical Sciences', NULL, NULL, 2018, 'gold', 'https://doi.org/10.26479/2018.0404.09', 0, 0, 0, 0, '2026-10-11T06:51:59.910576+00:00', '2026-10-11T06:51:59.910576+00:00'),
  ('d1b10f22-2b70-4326-9542-7cf258ad60f6', '10.1038/s41586-026-10689-z', 'https://doi.org/10.1038/s41586-026-10689-z', 'Universal cell embedding provides a foundation model for cell biology', 'Developing a universal representation space for cells that encompasses the tremendous molecular diversity of cell types across species would be transformative for cell biology. Recent work using single-cell transcriptomic approaches to create molecular definitions of cell types in the form of cell atlases has provided the necessary data for such an endeavour1-3. Here we present the universal cell embedding (UCE) foundation model. UCE was trained on a large corpus of cell data using self-supervision, creating a unified biological latent space that can represent cells across diverse tissues and species. This latent space captures important biological variation despite the presence of experimental noise. UCE''s universality means that new cells can be embedded with no data labelling, model training or fine-tuning. We used UCE to create the Integrated Mega-scale Atlas, embedding 36 million cells, with more than 1,000 uniquely named cell types, from hundreds of experiments, dozens of tissues and eight species. We gain insights into the organization of cell types and tissues within the space. UCE''s embedding space exhibits emergent behaviour, identifying biology that it was never trained for, such as identifying developmental lineages and embedding data from species that were not included in the training set. Overall, by enabling a universal representation for every cell state and type, UCE is a valuable tool for analysis, annotation and hypothesis generation over single-cell data.', 'Nature', NULL, NULL, 2026, 'gold', 'https://europepmc.org/backend/ptpmcrender.fcgi?accid=PMC13441871&blobtype=pdf', 0, 0, 0, 0, '2026-10-11T17:48:21.772435+00:00', '2026-10-11T17:48:21.772435+00:00'),
  ('c42b16d3-5223-4eb2-8638-5b9587a69c7f', '10.1021/acssynbio.6c00178', 'https://doi.org/10.1021/acssynbio.6c00178', 'Nanofluidics for Pioneering Synthetic Biology of Bottom-Up Cell-Free Molecular Systems', 'Synthetic biology via bottom-up assembly is transitioning from stochastic, extract-based cell-free systems toward reconstituted, molecularly defined cell-free molecular systems. Transitioning to molecularly defined systems provides a path to quantitative design; however, the active assembly of these molecular building blocks into ordered spatiotemporal architectures remains a formidable challenge in synthetic biology. In this perspective, we propose nanofluidics as a transformative platform to bridge this gap. By leveraging nanoconfinement effects and precision mass transport, nanofluidics facilitates the active assembly of molecular building blocks into functionally integrated spatiotemporal structures, thereby pioneering the synthetic biology of bottom-up cell-free molecular systems. Specifically, we discuss how nanofluidics enables precise control over fluid dynamics and single-molecule behavior within nanochannels and facilitates molecular active-assembly and tunable interactions of molecular components by engineering design of nanofluidic devices. Furthermore, we highlight key challenges and opportunities using nanofluidics to build next-generation cell-free molecular systems with single-molecule resolution. This perspective provides a strategic roadmap for the synthetic biology of bottom-up cell-free molecular systems.', 'ACS synthetic biology', NULL, NULL, 2026, 'gold', 'https://europepmc.org/backend/ptpmcrender.fcgi?accid=PMC13386641&blobtype=pdf', 0, 0, 0, 0, '2026-10-14T04:50:39.499123+00:00', '2026-10-14T04:50:39.499123+00:00'),
  ('1a633bcc-a313-4488-9e82-139b706a6001', '10.1093/bib/bbaa279', 'https://doi.org/10.1093/bib/bbaa279', 'InstaDock: A single-click graphical user interface for molecular docking-based virtual high-throughput screening', 'Exploring protein-ligand interactions is a subject of immense interest, as it provides deeper insights into molecular recognition, mechanism of interaction and subsequent functions. Predicting an accurate model for a protein-ligand interaction is a challenging task. Molecular docking is a computational method used for predicting the preferred orientation, binding conformations and the binding affinity of a ligand to a macromolecular target, especially protein. It has been applied in ''virtual high-throughput screening'' of chemical libraries containing millions of compounds to find potential leads in drug design and discovery. Here, we have developed InstaDock, a free and open access Graphical User Interface (GUI) program that performs molecular docking and high-throughput virtual screening efficiently. InstaDock is a single-click GUI that uses QuickVina-W, a modified version of AutoDock Vina for docking calculations, made especially for the convenience of non-bioinformaticians and for people who are not experts in using computers. InstaDock facilitates onboard analysis of docking and visual results in just a single click. To sum up, InstaDock is the easiest and more interactive interface than ever existing GUIs for molecular docking and high-throughput virtual screening. InstaDock is freely available for academic and industrial research purposes via https://hassanlab.org/instadock.', 'Briefings in Bioinformatics', 'Oxford University Press', NULL, 2020, 'closed', NULL, 0, 2, 0, 3, '2026-10-03T13:44:42.438909+00:00', '2026-10-03T13:44:42.438909+00:00')
